const CACHE='jadwaly-public-v4';
const ASSETS=['./','./index.html','./portal.js','./portal.css','./simple.css','./settings.css','./theme.js','./favicon.ico','./schedule-model.js','./timetable.json','./icon.svg','./manifest.webmanifest','./fonts/IBMPlexSansArabic-Regular.ttf','./fonts/IBMPlexSansArabic-SemiBold.ttf','./timetable-2026-2027.pdf'];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const path of ASSETS){const url=new URL(path,self.registration.scope);const response=await fetch(new Request(url,{cache:'reload',credentials:'same-origin'}));if(!response.ok||response.redirected||new URL(response.url).origin!==url.origin)throw new Error('Unavailable asset');if(path==='./'||path==='./index.html'){const text=await response.clone().text();if(!text.includes('src="./portal.js"'))throw new Error('Unexpected shell');}await cache.put(url,response);}await self.skipWaiting();})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{await Promise.all((await caches.keys()).filter(k=>(k.startsWith('gadwaly-g5-')||k.startsWith('jadwaly-public-'))&&k!==CACHE).map(k=>caches.delete(k)));await self.clients.claim();})()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;const known=ASSETS.some(p=>new URL(p,self.registration.scope).pathname===url.pathname);if(event.request.mode==='navigate'&&known){event.respondWith(fetch(event.request).catch(async()=>await caches.match(event.request,{ignoreSearch:true})||await caches.match(new URL('./',self.registration.scope))||Response.error()));}else if(known){event.respondWith(fetch(event.request).then(async response=>{if(response.ok&&!response.redirected){const cache=await caches.open(CACHE);await cache.put(new Request(url.origin+url.pathname),response.clone());}return response;}).catch(()=>caches.match(event.request,{ignoreSearch:true})));}});
